--
-- Name: customer_analytics; Type: VIEW; Schema: warehouse; Owner: petflow
--

CREATE VIEW warehouse.customer_analytics AS
 WITH delivered_orders AS (
         SELECT fo.order_id,
            fo.customer_key,
            fo.order_purchase_timestamp,
            fo.order_value
           FROM warehouse.fact_order fo
          WHERE (((fo.order_status)::text = 'delivered'::text) AND (fo.order_purchase_timestamp <= '2018-08-31 23:59:59'::timestamp without time zone))
        ), customer_behavior AS (
         SELECT dc.customer_key,
            dc.customer_unique_id,
            dc.customer_city,
            dc.customer_state,
            min(d.order_purchase_timestamp) AS first_purchase_date,
            max(d.order_purchase_timestamp) AS last_purchase_date,
            count(DISTINCT d.order_id) AS total_orders,
            sum(d.order_value) AS total_spent,
            avg(d.order_value) AS average_order_value
           FROM (delivered_orders d
             JOIN warehouse.dim_customer dc ON ((d.customer_key = dc.customer_key)))
          GROUP BY dc.customer_key, dc.customer_unique_id, dc.customer_city, dc.customer_state
        )
 SELECT customer_key,
    customer_unique_id,
    customer_city,
    customer_state,
    first_purchase_date,
    last_purchase_date,
    total_orders,
    round(total_spent, 2) AS total_spent,
    round(average_order_value, 2) AS average_order_value,
    round((EXTRACT(epoch FROM ('2018-08-31 23:59:59'::timestamp without time zone - last_purchase_date)) / (86400)::numeric), 2) AS days_since_last_purchase,
        CASE
            WHEN (total_orders >= 2) THEN 'repeat'::text
            ELSE 'one_time'::text
        END AS customer_type
   FROM customer_behavior;


ALTER VIEW warehouse.customer_analytics OWNER TO petflow;

--
-- Name: customer_rfm; Type: VIEW; Schema: warehouse; Owner: petflow
