CREATE VIEW warehouse.customer_rfm AS
 SELECT customer_key,
    customer_unique_id,
    customer_city,
    customer_state,
    total_orders,
    total_spent,
    average_order_value,
    days_since_last_purchase,
    recency_score,
    frequency_score,
    monetary_score,
    rfm_score,
        CASE
            WHEN (rfm_score >= 13) THEN 'high_value'::text
            WHEN (rfm_score >= 10) THEN 'loyal'::text
            WHEN ((rfm_score >= 8) AND (days_since_last_purchase <= (60)::numeric)) THEN 'recent'::text
            WHEN ((rfm_score >= 6) AND (days_since_last_purchase <= (120)::numeric)) THEN 'developing'::text
            WHEN (days_since_last_purchase <= (240)::numeric) THEN 'at_risk'::text
            ELSE 'inactive'::text
        END AS customer_segment
   FROM ( SELECT customer_analytics.customer_key,
            customer_analytics.customer_unique_id,
            customer_analytics.customer_city,
            customer_analytics.customer_state,
            customer_analytics.total_orders,
            customer_analytics.total_spent,
            customer_analytics.average_order_value,
            customer_analytics.days_since_last_purchase,
                CASE
                    WHEN (customer_analytics.days_since_last_purchase <= (30)::numeric) THEN 5
                    WHEN (customer_analytics.days_since_last_purchase <= (60)::numeric) THEN 4
                    WHEN (customer_analytics.days_since_last_purchase <= (120)::numeric) THEN 3
                    WHEN (customer_analytics.days_since_last_purchase <= (240)::numeric) THEN 2
                    ELSE 1
                END AS recency_score,
                CASE
                    WHEN (customer_analytics.total_orders >= 10) THEN 5
                    WHEN (customer_analytics.total_orders >= 5) THEN 4
                    WHEN (customer_analytics.total_orders >= 3) THEN 3
                    WHEN (customer_analytics.total_orders = 2) THEN 2
                    ELSE 1
                END AS frequency_score,
                CASE
                    WHEN (customer_analytics.total_spent <= 55.24) THEN 1
                    WHEN (customer_analytics.total_spent <= 87.35) THEN 2
                    WHEN (customer_analytics.total_spent <= 132.642) THEN 3
                    WHEN (customer_analytics.total_spent <= 208.532) THEN 4
                    ELSE 5
                END AS monetary_score,
            ((
                CASE
                    WHEN (customer_analytics.days_since_last_purchase <= (30)::numeric) THEN 5
                    WHEN (customer_analytics.days_since_last_purchase <= (60)::numeric) THEN 4
                    WHEN (customer_analytics.days_since_last_purchase <= (120)::numeric) THEN 3
                    WHEN (customer_analytics.days_since_last_purchase <= (240)::numeric) THEN 2
                    ELSE 1
                END +
                CASE
                    WHEN (customer_analytics.total_orders >= 10) THEN 5
                    WHEN (customer_analytics.total_orders >= 5) THEN 4
                    WHEN (customer_analytics.total_orders >= 3) THEN 3
                    WHEN (customer_analytics.total_orders = 2) THEN 2
                    ELSE 1
                END) +
                CASE
                    WHEN (customer_analytics.total_spent <= 55.24) THEN 1
                    WHEN (customer_analytics.total_spent <= 87.35) THEN 2
                    WHEN (customer_analytics.total_spent <= 132.642) THEN 3
                    WHEN (customer_analytics.total_spent <= 208.532) THEN 4
                    ELSE 5
                END) AS rfm_score
           FROM warehouse.customer_analytics) base;


